// Handle WebSocket connection and session management
const connectionData = $input.first().json;
const { sessionId, userId, characterId, clientType = 'player' } = connectionData;

// Validate required fields
if (!sessionId || !userId || !characterId) {
  throw new Error('Missing required fields: sessionId, userId, characterId');
}

// Generate unique connection ID
const connectionId = `conn_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Connection metadata
const connectionMetadata = {
  connectionId,
  sessionId,
  userId,
  characterId,
  clientType, // 'player', 'dm', 'observer', 'ai-agent'
  connectedAt: new Date().toISOString(),
  lastActivity: new Date().toISOString(),
  status: 'connected',
  clientInfo: {
    userAgent: connectionData.userAgent || 'unknown',
    ipAddress: connectionData.ipAddress || 'unknown',
    platform: connectionData.platform || 'web'
  },
  capabilities: {
    audio: connectionData.capabilities?.audio || false,
    video: connectionData.capabilities?.video || false,
    screenShare: connectionData.capabilities?.screenShare || false
  }
};

return { json: connectionMetadata };

// Update session participant list and notify others
const connectionData = $input.first().json;
const { sessionId, userId, characterId, connectionId } = connectionData;

// Get current session participants
const sessionData = await $getGoogleFirestoreItem('game_sessions', sessionId);
const currentParticipants = sessionData?.participants || [];

// Add new participant if not already present
if (!currentParticipants.find(p => p.connectionId === connectionId)) {
  currentParticipants.push({
    connectionId,
    userId,
    characterId,
    joinedAt: new Date().toISOString(),
    status: 'active'
  });
}

// Update session with new participant list
await $setGoogleFirestoreItem('game_sessions', sessionId, {
  participants: currentParticipants,
  lastActivity: new Date().toISOString(),
  participantCount: currentParticipants.length
});

// Prepare notification for other participants
const joinNotification = {
  type: 'participant_joined',
  sessionId,
  timestamp: new Date().toISOString(),
  data: {
    connectionId,
    userId,
    characterId,
    totalParticipants: currentParticipants.length
  }
};

return {
  json: {
    ...connectionData,
    sessionParticipants: currentParticipants,
    notification: joinNotification
  }
};

// Broadcast join notification to other participants
const data = $input.first().json;
const { sessionId, connectionId, notification, sessionParticipants } = data;

// Get other participants (exclude the new connection)
const otherParticipants = sessionParticipants.filter(p => p.connectionId !== connectionId);

// Prepare broadcast messages
const broadcasts = otherParticipants.map(participant => ({
  endpoint: `/websocket/session/${sessionId}/connection/${participant.connectionId}`,
  message: {
    ...notification,
    recipientConnectionId: participant.connectionId
  }
}));

return broadcasts.map(broadcast => ({ json: broadcast }));

// Process incoming WebSocket message
const messageData = $input.first().json;
const { sessionId, connectionId, messageType, payload, targetConnectionId } = messageData;

// Validate required fields
if (!sessionId || !connectionId || !messageType) {
  throw new Error('Missing required fields: sessionId, connectionId, messageType');
}

// Validate connection exists
const connection = await $getGoogleFirestoreItem('websocket_connections', connectionId);
if (!connection || connection.status !== 'connected') {
  throw new Error('Invalid or disconnected connection');
}

// Process message based on type
const processedMessage = {
  messageId: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
  sessionId,
  connectionId,
  messageType,
  targetConnectionId, // null = broadcast to all in session
  payload,
  timestamp: new Date().toISOString(),
  senderInfo: {
    userId: connection.userId,
    characterId: connection.characterId,
    clientType: connection.clientType
  }
};

return { json: processedMessage };

// Route direct message to specific connection
const messageData = $input.first().json;
const { sessionId, targetConnectionId } = messageData;

// Validate target connection exists
const targetConnection = await $getGoogleFirestoreItem('websocket_connections', targetConnectionId);
if (!targetConnection || targetConnection.status !== 'connected') {
  throw new Error('Target connection not found or disconnected');
}

// Validate target is in same session
if (targetConnection.sessionId !== sessionId) {
  throw new Error('Target connection not in same session');
}

return [{
  json: {
    endpoint: `/websocket/session/${sessionId}/connection/${targetConnectionId}`,
    message: messageData
  }
}];

// Broadcast message to all participants in session
const messageData = $input.first().json;
const { sessionId, connectionId } = messageData;

// Get all session participants
const sessionData = await $getGoogleFirestoreItem('game_sessions', sessionId);
const participants = sessionData?.participants || [];

// Create broadcast targets (exclude sender)
const broadcastTargets = participants
  .filter(p => p.connectionId !== connectionId)
  .map(participant => ({
    endpoint: `/websocket/session/${sessionId}/connection/${participant.connectionId}`,
    message: messageData
  }));

return broadcastTargets.map(target => ({ json: target }));

// Handle WebSocket disconnection
const disconnectData = $input.first().json;
const { sessionId, connectionId, reason = 'client_disconnect' } = disconnectData;

// Validate connection exists
const connection = await $getGoogleFirestoreItem('websocket_connections', connectionId);
if (!connection) {
  throw new Error('Connection not found');
}

// Update connection status
await $setGoogleFirestoreItem('websocket_connections', connectionId, {
  status: 'disconnected',
  disconnectedAt: new Date().toISOString(),
  disconnectReason: reason
});

// Update session participants
const sessionData = await $getGoogleFirestoreItem('game_sessions', sessionId);
const participants = sessionData?.participants || [];
const updatedParticipants = participants.filter(p => p.connectionId !== connectionId);

await $setGoogleFirestoreItem('game_sessions', sessionId, {
  participants: updatedParticipants,
  lastActivity: new Date().toISOString(),
  participantCount: updatedParticipants.length
});

// Prepare leave notification
const leaveNotification = {
  type: 'participant_left',
  sessionId,
  timestamp: new Date().toISOString(),
  data: {
    connectionId,
    userId: connection.userId,
    characterId: connection.characterId,
    reason,
    remainingParticipants: updatedParticipants.length
  }
};

return {
  json: {
    connectionId,
    sessionId,
    userId: connection.userId,
    characterId: connection.characterId,
    disconnectReason: reason,
    notification: leaveNotification,
    remainingParticipants: updatedParticipants
  }
};

// Broadcast disconnect notification to remaining participants
const data = $input.first().json;
const { sessionId, notification, remainingParticipants } = data;

// Broadcast to all remaining participants
const broadcasts = remainingParticipants.map(participant => ({
  endpoint: `/websocket/session/${sessionId}/connection/${participant.connectionId}`,
  message: notification
}));

return broadcasts.map(broadcast => ({ json: broadcast }));
